        o = B.totalizer(lits)
        if target < 0 or target > len(o):
            cl.append([])
            continue
        if target >= 1:
            cl.append([o[target - 1]])
        if target < len(o):
            cl.append([-o[target]])
    # first-occurrence order (P0 triple labels; equal-count special labels)
    for c in range(K):
        if c < c0:
            prs = [(s, s + 1) for s in range(1 if base_quad else 0, Q - 1)]
        else:
